"INSERT OR IGNORE INTO events (slug, city, title, organization_id, venue_name, venue_address, start_at, end_at, start_utc, end_utc, timezone, format, description_short, description_long, registration_url, cost_type, cost_min, cost_max, cost_notes, cpe_eligible, cpe_hours, cpe_body, cpe_notes, topics, audience_level, status, source, source_url, reviewer_notes, hold, auto_publish_at) VALUES ('21st-annual-api-cybersecurity-conference-for-the-oil-and-natural-gas-industry-2026-11-10', 'houston', '21st Annual API Cybersecurity Conference for the Oil and Natural Gas Industry', (SELECT id FROM organizations WHERE slug='api-cybersecurity-conference'), 'Woodlands Waterway Marriott Hotel & Convention Center', '1601 Lake Robbins Dr, The Woodlands, TX 77380', '2026-11-10T08:00:00', '2026-11-10T10:00:00', '2026-11-10T14:00:00.000Z', '2026-11-10T16:00:00.000Z', 'America/Chicago', 'in_person', 'Two-day conference titled Protecting Energy Through Cybersecurity, with more than 60 presentations across three tracks covering OT and ICS security, zero trust, threat hunting, identity and access man', 'Two-day conference titled Protecting Energy Through Cybersecurity, with more than 60 presentations across three tracks covering OT and ICS security, zero trust, threat hunting, identity and access management, and generative AI risk. Keynotes from Tyler Williams (EY) and Dd Budiharto (Microsoft), with Mario Chiock (SLB) on day two.', 'https://cvent.me/e90raZ', 'paid', 595.0, 995.0, 'API members $895, non-members $995, government and academic $595 (prices after Sept 25)', 1, NULL, 'self_reported', 'CPE offered (hours not stated)', '[\"network\", \"threat_intel\", \"identity\", \"ai\"]', 'practitioner', 'pending_review', 'research', 'https://events.api.org/?p=4564', 'Research 2026-10-22 from https://events.api.org/?p=4564. Publishes automatically in 24 hours unless held or rejected. Research note: Sessions run 8:00-17:30 on Nov 10 and 8:00-17:15 on Nov 11, with receptions after each day. Cancellation refundable less $100 until Oct 9.', 0, datetime('now','+1 day'));",
